import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

/** Creates an isolated temporary folder for an integration test. Call `cleanup()` in `afterEach`. */
export function createTempDir(prefix = 'careerly-test-') {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), prefix));
  return {
    dir,
    cleanup: () => fs.rmSync(dir, { recursive: true, force: true }),
  };
}

/** The real migrations generated by drizzle-kit. */
export const MIGRATIONS_DIR = path.resolve(import.meta.dirname, '..', '..', 'drizzle');

/** Tags of the real migrations, in order (read from the drizzle-kit journal). */
export const MIGRATION_TAGS: string[] = (
  JSON.parse(fs.readFileSync(path.join(MIGRATIONS_DIR, 'meta', '_journal.json'), 'utf8')) as {
    entries: { idx: number; tag: string }[];
  }
).entries
  .sort((a, b) => a.idx - b.idx)
  .map((entry) => entry.tag);
